import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    TorusGeometry,
    Vector3,
    Color,
    PointLight,
    DoubleSide
  } = THREE;

  const visualSpec = config.intent?.visualSpec ?? {};
  const palette = visualSpec.colors ?? {};
  const ink = palette.ink ?? '#16161d';
  const paper = palette.paper ?? '#e8ecf2';
  const accent = palette.accent ?? '#ff2a38';
  const surface = palette.surface ?? '#0b0b10';

  const root = new Group();
  root.name = config.id ?? 'collection-stat-tile';
  root.userData.handlers = {};

  const ownedResources = [];
  const primitiveResults = [];
  let disposed = false;

  const track = (resource) => {
    if (resource) ownedResources.push(resource);
    return resource;
  };

  const makeBasicGradient = () => {
    const stops = Array.isArray(visualSpec.gradientStops) && visualSpec.gradientStops.length > 1
      ? visualSpec.gradientStops
      : [surface, ink];

    const bottom = typeof stops[0] === 'string' ? stops[0] : surface;
    const top = typeof stops[stops.length - 1] === 'string' ? stops[stops.length - 1] : ink;

    const material = track(new MeshBasicNodeMaterial({
      side: DoubleSide,
      depthWrite: false
    }));

    material.colorNode = mix(bottom, top, uv().y);
    return material;
  };

  const backdrop = new Mesh(
    track(new PlaneGeometry(7, 6)),
    makeBasicGradient()
  );
  backdrop.name = 'designed-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const contactMaterial = track(new MeshBasicNodeMaterial({
    color: new Color(surface),
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  }));

  const contactShadow = new Mesh(
    track(new CircleGeometry(1.65, 64)),
    contactMaterial
  );
  contactShadow.name = 'radial-contact-shadow';
  contactShadow.rotation.x = -Math.PI * 0.5;
  contactShadow.position.set(0, -0.92, -0.22);
  root.add(contactShadow);

  const backingMaterial = track(new MeshStandardNodeMaterial({
    color: new Color(ink),
    roughness: 0.62,
    metalness: 0.48
  }));

  const backing = new Mesh(
    track(new BoxGeometry(2.8, 1.72, 0.18)),
    backingMaterial
  );
  backing.name = 'machined-stat-surface';
  backing.position.set(0, 0, -0.12);
  root.add(backing);

  const rimMaterial = track(new MeshStandardNodeMaterial({
    color: new Color(accent),
    emissive: new Color(accent),
    emissiveIntensity: 1.15,
    roughness: 0.58,
    metalness: 0.42
  }));

  const rim = new Mesh(
    track(new TorusGeometry(1.06, 0.025, 10, 96)),
    rimMaterial
  );
  rim.name = 'signal-red-accent-rim';
  rim.rotation.x = Math.PI * 0.5;
  rim.rotation.z = Math.PI * 0.5;
  rim.position.set(0.92, 0, 0.02);
  rim.scale.set(0.58, 1, 1);
  root.add(rim);

  const keyLight = new PointLight(new Color(paper), 1.1, 7, 2);
  keyLight.position.set(2.8, 2.6, 3.6);
  keyLight.name = 'product-key-light';
  root.add(keyLight);

  const rimLight = new PointLight(new Color(accent), 0.75, 5, 2);
  rimLight.position.set(-2.2, 1.1, 2.2);
  rimLight.name = 'accent-rim-light';
  root.add(rimLight);

  const fillLight = new PointLight(new Color(ink), 0.35, 5, 2);
  fillLight.position.set(0, -1.8, 1.8);
  fillLight.name = 'machined-surface-fill';
  root.add(fillLight);

  const contentRoot = new Group();
  contentRoot.name = 'stat-asset-content';
  contentRoot.position.set(0, -0.4, 0.05);
  contentRoot.scale.setScalar(0.96);
  root.add(contentRoot);

  const entrance = gsap.timeline({ paused: false });
  entrance
    .to(contentRoot.position, {
      y: 0,
      duration: 0.7,
      ease: 'power3.out'
    })
    .to(contentRoot.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.34,
      ease: 'power4.out'
    }, '<0.18')
    .to(contentRoot.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out'
    });

  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(contentRoot.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out'
  });

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string' || !item.text) continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role === 'accent' ? accent : paper,
      align: item.typography?.align ?? 'center',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.set(0, item.role === 'label' ? -0.52 : 0.32, 0.28);
    contentRoot.add(textObject);
  }

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;

      const scene = gltf.scene;
      scene.name = 'machined-gear-stat-mesh';

      const bounds = new THREE.Box3().setFromObject(scene);
      const size = bounds.getSize(new Vector3());
      const maxDimension = Math.max(size.x, size.y, size.z) || 1;
      const fitScale = 1.32 / maxDimension;

      scene.scale.setScalar(fitScale);
      scene.position.set(0, 0.02, 0.22);
      contentRoot.add(scene);
    }).catch(() => {});
  }

  const primitives = Array.isArray(config.cinematicPrimitives)
    ? config.cinematicPrimitives
    : [];

  for (const primitive of primitives) {
    if (!primitive?.name || typeof ctx.primitives?.[primitive.name] !== 'function') continue;

    const result = ctx.primitives[primitive.name](root, primitive.params ?? {});
    if (result) primitiveResults.push(result);
  }

  root.userData.handlers.hover = (active = true) => {
    if (disposed) return;
    if (active) hoverTimeline.play();
    else hoverTimeline.reverse();
  };

  root.userData.handlers.click = () => {
    if (disposed) return;

    gsap.timeline()
      .to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      })
      .to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.28,
        ease: 'back.out(2)'
      });

    ctx.emit('hub-collection.select', {
      nodeId: config.id ?? 'collection-stat-tile'
    });
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    entrance.kill();
    hoverTimeline.kill();

    for (const result of primitiveResults) {
      if (typeof result?.timeline?.kill === 'function') result.timeline.kill();
      if (typeof result?.cleanup === 'function') result.cleanup();
    }

    root.traverse((object) => {
      if (object.geometry && typeof object.geometry.dispose === 'function') {
        object.geometry.dispose();
      }

      const material = object.material;
      if (Array.isArray(material)) {
        for (const entry of material) {
          if (entry && typeof entry.dispose === 'function') entry.dispose();
        }
      } else if (material && typeof material.dispose === 'function') {
        material.dispose();
      }
    });

    for (const resource of ownedResources) {
      if (resource && typeof resource.dispose === 'function') resource.dispose();
    }

    root.clear();
  };

  return root;
}
